const currencyOptions = (selected='PEN') => Object.entries(currencies).map(([code,name])=>'<option value="'+code+'"'+(code===selected?' selected':'')+'>'+name+' ('+code+')</option>').join('');
const eventCurrency = () => state.events.find(e=>e.id===state.eventId)?.currency || 'CLP';
const money = (value,currency=eventCurrency()) => new Intl.NumberFormat(currency==='CLP'?'es-CL':'es-PE',{style:'currency',currency,currencyDisplay:'code',minimumFractionDigits:value%100?2:0,maximumFractionDigits:2}).format((value||0)/100);
