function toast(message){const el=$('#toast');el.textContent=message;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4500);}
function formData(form){return Object.fromEntries(new FormData(form));}
function errorAt(form,message){const el=$('.error',form);if(el)el.textContent=message;else toast(message);}
function runForm(form,callback){form.onsubmit=async e=>{e.preventDefault();if(form.dataset.busy)return;form.dataset.busy='1';errorAt(form,'');const buttons=$$('button',form),disabled=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);try{await callback(formData(form),e.submitter);}catch(err){errorAt(form,err.message);}finally{delete form.dataset.busy;buttons.forEach((b,i)=>b.disabled=disabled[i]);}};}
async function api(path,{method='GET',data,operationKey}={}){
 const controller=new AbortController(), timer=setTimeout(()=>controller.abort(),20000);let response;
 try{response=await fetch(path,{method,credentials:'same-origin',signal:controller.signal,headers:{'Content-Type':'application/json','X-Requested-With':'Acceso',...(state.csrf?{'X-CSRF-Token':state.csrf}:{}),...(operationKey?{'Idempotency-Key':operationKey}:{})},...(data!==undefined?{body:JSON.stringify(data)}:{})});}
 catch(e){const err=new Error('Sin respuesta del servidor. Reintenta la operación pendiente para comprobar si se registró.');err.uncertain=true;throw err;}finally{clearTimeout(timer);}
 const result=await response.json().catch(()=>null);
 if(!response.ok||!result){const err=new Error(result?.error||'El servidor no pudo completar la operación.');err.status=response.status;err.uncertain=response.status>=500||!result;if(response.status===401&&state.user){state.user=null;state.csrf=null;stopScreen();$$('dialog').forEach(d=>d.remove());$('#printArea').innerHTML='';authScreen(false);}throw err;}return result;
}
function pendingStorage(){return 'acceso.pending.'+state.user?.id;}
function savePending(){if(state.pending)sessionStorage.setItem(pendingStorage(),JSON.stringify(state.pending));else sessionStorage.removeItem(pendingStorage());pendingBanner();}
async function mutate(path,data,method='POST'){if(state.pending)throw new Error('Resuelve la operación pendiente antes de registrar otra.');state.pending={path,data,method,operationKey:key()};savePending();return resolvePending();}
async function resolvePending(){if(resolving)throw new Error('La operación todavía está en curso');const pending=state.pending;if(!pending)return;resolving=true;pendingBanner();try{const result=await api(pending.path,{...pending});state.pending=null;savePending();if(pending.path==='/api/sales/quick'){state.lastSale={...result,event:state.events.find(e=>e.id===pending.data.eventId)};sessionStorage.setItem('acceso.receipt.'+state.user.id,JSON.stringify(state.lastSale));}return result;}catch(e){if(!e.uncertain&&e.status!==401){state.pending=null;savePending();}else pendingBanner();throw e;}finally{resolving=false;pendingBanner();}}
function pendingBanner(){
 const box=$('#pending');if(!box)return;box.hidden=!state.pending;if(!state.pending)return;
 box.innerHTML='<strong>Operación pendiente de confirmación</strong><p>No vuelvas a cobrar. Comprueba el resultado usando el mismo registro.</p><button id="retryPending">Comprobar / reintentar</button>';
 $('#retryPending').disabled=resolving;
 $('#retryPending').onclick=async()=>{const button=$('#retryPending');button.disabled=true;const path=state.pending?.path;
 try{const result=await resolvePending();try{await refresh();}catch(e){}render();
 if(path==='/api/sales/quick')showReceipt(state.lastSale);
 else if(path==='/api/validate'){const ok=result.result==='VALID';modal(`<div class="scan-result ${ok?'valid':'bad'}"><h2>${ok?'Puede pasar':'No permitir el ingreso'}</h2><p>${esc(result.detail)}</p></div><button data-close class="inline-form">Continuar</button>`);}
 else toast('Operación confirmada');
 }catch(e){toast(e.message);if(button.isConnected)button.disabled=false;}};
}
async function refresh(){const data=await api('/api/bootstrap');Object.assign(state,{events:data.events,tariffs:data.tariffs,stats:data.stats});if(!state.eventId)state.eventId=state.events.find(e=>e.status==='activo')?.id||state.events[0]?.id||null;const marker=$('#sync');if(marker&&state.tab!=='tickets')marker.textContent='Actualizado '+new Date().toLocaleTimeString('es-CL');}
function stopScreen(){screen++;if(cleanup){cleanup();cleanup=null;}}
