function cancelModal(id,reload){const dialog=modal('<h2>Cancelar entrada</h2><p>Bloquea su QR. Esta acción no devuelve dinero; cualquier devolución debe registrarse por separado en caja.</p><form class="stack"><label>Motivo<input name="reason" required maxlength="300"></label><p class="error" role="alert"></p><button class="danger">Confirmar cancelación</button></form><button data-close class="inline-form">Volver</button>');runForm($('form',dialog),async data=>{await mutate('/api/tickets/'+id+'/cancel',data);dialog.close();await reload();});}
async function cashScreen(){const generation=screen;const data=await api('/api/cash');if(screen!==generation)return;$('#content').innerHTML=heading('Caja','Totales de todo el historial, separados por moneda y medio de pago. Los movimientos antiguos conservan la categoría “sin clasificar”.')+`<div class="stats">${data.totals.map(t=>`<div class="stat">${esc(t.method)}<b>${money(t.income-t.withdrawals,t.currency)}</b><small>Ingresos ${money(t.income,t.currency)}<br>Retiros ${money(t.withdrawals,t.currency)}</small></div>`).join('')||'<p>Sin movimientos</p>'}</div><section class="panel"><h2>Registrar movimiento manual</h2><form id="cashForm" class="stack"><div class="row"><label>Tipo<select name="type"><option value="INGRESO">Ingreso</option><option value="RETIRO">Retiro / devolución</option></select></label><label>Medio<select name="method"><option value="efectivo">Efectivo</option><option value="transferencia">Transferencia</option><option value="tarjeta">Tarjeta</option></select></label><label>Moneda<select name="currency">${currencyOptions()}</select></label><label>Monto<input name="amount" type="number" min="0.01" step="0.01" required></label></div><label>Descripción / referencia<input name="description" required maxlength="300" placeholder="Motivo y número de entrada si es una devolución"></label><p class="error" role="alert"></p><button class="primary">Registrar movimiento</button></form></section><section class="panel"><h2>Últimos 100 movimientos</h2><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Medio</th><th>Monto</th><th>Descripción</th><th>Responsable</th></tr></thead><tbody>${data.movements.map(m=>`<tr><td>${dateTime(m.date)}</td><td>${esc(m.type)}</td><td>${esc(m.method)}</td><td>${money(m.amount_cents,m.currency)}</td><td>${esc(m.description)}</td><td>${esc(m.user_name)}</td></tr>`).join('')}</tbody></table></div></section>`;runForm($('#cashForm'),async data=>{await mutate('/api/cash',{...data,amount:Number(data.amount)});render();toast('Movimiento registrado');});}
async function usersScreen(){const generation=screen,data=await api('/api/users');if(screen!==generation)return;$('#content').innerHTML=heading('Personal','Cada trabajador tiene su cuenta. Desactivar una cuenta cierra sus sesiones.')+`<div class="grid"><section class="panel"><h2>Crear cuenta</h2><form id="userForm" class="stack"><label>Nombre<input name="name" required maxlength="100"></label><label>Usuario<input name="username" required maxlength="60" autocomplete="off" autocapitalize="none"></label><label>Contraseña inicial<input name="password" type="password" required minlength="10" maxlength="200" autocomplete="new-password"></label><label>Rol<select name="role" aria-label="Rol"><option value="vendedor">Vendedor: ventas y abonos</option><option value="validador">Validador: solo acceso</option><option value="admin">Administrador: gestión completa</option></select></label><p class="error" role="alert"></p><button class="primary">Crear cuenta</button></form></section><section class="panel"><h2>Equipo</h2>${data.users.map(u=>`<div class="inline-form"><strong>${esc(u.name)}</strong><p>${esc(u.username)} · ${esc(u.role)} · ${u.active?'Activo':'Inactivo'}</p>${u.id!==state.user.id?`<button data-user="${u.id}" data-active="${u.active?'false':'true'}">${u.active?'Desactivar':'Activar'}</button>`:''}</div>`).join('')}</section></div>`;runForm($('#userForm'),async data=>{await api('/api/users',{method:'POST',data});render();toast('Cuenta creada');});$$('[data-user]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/api/users/'+b.dataset.user,{method:'PATCH',data:{active:b.dataset.active==='true'}});render();}catch(e){toast(e.message);b.disabled=false;}});}
async function auditScreen(){const generation=screen,data=await api('/api/audit');if(screen!==generation)return;$('#content').innerHTML=heading('Auditoría','Últimas 200 operaciones y validaciones. El responsable se obtiene de la sesión autenticada.')+`<section class="panel"><h2>Operaciones</h2><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Personal</th><th>Operación</th><th>Detalle</th></tr></thead><tbody>${data.audit.map(a=>`<tr><td>${dateTime(a.date)}</td><td>${esc(a.name)}</td><td>${esc(a.action)}</td><td class="mono">${esc(a.detail)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Validaciones (incluye historial anterior)</h2><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Personal</th><th>Resultado</th><th>Entrada</th></tr></thead><tbody>${data.validations.map(v=>`<tr><td>${dateTime(v.date)}</td><td>${esc(v.user_name)}</td><td>${esc(v.result)}</td><td class="mono">${esc(v.ticket_id)}</td></tr>`).join('')}</tbody></table></div></section>`;}
async function boot(){try{const status=await api('/api/auth/status');if(status.user){state.user=status.user;state.csrf=status.csrf;await enter();}else authScreen(status.setupRequired);}catch(e){$('#app').innerHTML=`<main class="login"><h1>No se pudo conectar</h1><p class="error">${esc(e.message)}</p><button id="bootRetry">Reintentar</button></main>`;$('#bootRetry').onclick=boot;}}
setInterval(async()=>{if(!state.user||document.hidden||polling)return;polling=true;try{await refresh();}catch(e){const marker=$('#sync');if(marker)marker.textContent='Sin conexión';}finally{polling=false;}},15000);
window.addEventListener('beforeunload',()=>{if(cleanup)cleanup();});
boot();

function individualSaleModal(ticket,reload){const rates=state.tariffs.filter(t=>t.event_id===ticket.event_id);const fixedRate=ticket.tariff_id?rates.find(t=>t.id===ticket.tariff_id):null;const rateOptions=fixedRate?`<option value="${fixedRate.id}">${esc(fixedRate.name)} · ${money(fixedRate.price_cents,ticket.currency)} · tarifa del lote</option>`:rates.map(t=>`<option value="${t.id}">${esc(t.name)} · ${money(t.price_cents,t.currency)}</option>`).join('');const dialog=modal(`<h2>Vender entrada / pago parcial</h2><form class="stack"><label>Tarifa<select name="tariffId" ${fixedRate?'disabled':''}>${rateOptions}</select>${fixedRate?`<input type="hidden" name="tariffId" value="${fixedRate.id}">`:''}</label><label>Nombre (opcional)<input name="customerName" maxlength="100"></label><label>Teléfono (opcional)<input name="customerPhone" maxlength="40" type="tel"></label><label>Pago inicial ${esc(ticket.currency)}<input name="initialPayment" type="number" min="0" step="0.01" value="${fixedRate?((fixedRate.price_cents||0)/100).toFixed(2):"0"}" required></label><label>Medio<select name="method"><option value="efectivo">Efectivo</option><option value="transferencia">Transferencia</option><option value="tarjeta">Tarjeta</option></select></label><p>${fixedRate?`Precio del lote: <strong>${money(fixedRate.price_cents,ticket.currency)}</strong>. El pago queda registrado por defecto como completo; si corresponde un abono, puedes modificarlo.`:`El QR no permitirá entrar hasta completar el pago.`}</p><p class="error" role="alert"></p><button class="primary" ${rates.length?'':'disabled'}>Confirmar venta y pago recibido</button></form><button data-close class="inline-form">Cerrar</button>`);runForm($('form',dialog),async data=>{await mutate('/api/tickets/'+ticket.id+'/sale',{...data,initialPayment:Number(data.initialPayment)});dialog.close();await reload();toast('Venta registrada');});}

async function settingsScreen(){
 $('#content').innerHTML=heading('Configuración','Restablecimiento del sistema')+`<section class="panel"><h2>Restablecer sistema</h2><p>Los QR anteriores dejarán de funcionar. Todas las sesiones se cerrarán. Hazlo al terminar la atención.</p><form id="resetPrepare" class="stack"><label>Qué deseas borrar<select name="mode"><option value="operations">Datos de operación: conservar usuarios</option><option value="full">Restablecimiento completo: volver a crear administrador</option></select></label><p>Ambas opciones eliminan eventos, entradas, ventas, pagos, caja e historial de auditoría. El restablecimiento completo elimina también las cuentas.</p><label>Contraseña del administrador<input name="password" type="password" required maxlength="200" autocomplete="current-password"></label><p class="error" role="alert"></p><button>Preparar respaldo</button></form><div id="resetConfirm"></div></section>`;
 runForm($('#resetPrepare'),async data=>{
  const result=await api('/api/system/reset/prepare',{method:'POST',data});
  $('#resetPrepare input[name="password"]').value='';
  $('#resetConfirm').innerHTML=`<div class="divider"></div><h3>${data.mode==='full'?'Restablecimiento completo':'Borrar datos de operación'}</h3><p>Descarga el respaldo antes de confirmar. Se guardará además una copia actualizada en la carpeta backups justo antes del borrado.</p><button id="downloadReset">Descargar respaldo</button><form id="resetExecute" class="stack inline-form"><label>Confirma tu contraseña<input name="password" type="password" required maxlength="200" autocomplete="current-password"></label><label>Escribe RESTABLECER<input name="confirmation" required autocomplete="off" pattern="RESTABLECER"></label><p class="error" role="alert"></p><button class="danger" id="resetFinal" disabled>Confirmar borrado definitivo</button></form>`;
  $('#downloadReset').onclick=async()=>{
   const button=$('#downloadReset');button.disabled=true;
   try{
    const response=await fetch('/api/system/reset/backup/'+result.token,{credentials:'same-origin'});
    if(!response.ok)throw new Error('No se pudo descargar el respaldo. Vuelve a preparar uno.');
    const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');
    link.href=url;link.download=result.filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);
    $('#resetFinal').disabled=false;
   }catch(e){errorAt($('#resetExecute'),e.message);}finally{button.disabled=false;}
  };
  runForm($('#resetExecute'),async confirmation=>{
   const outcome=await api('/api/system/reset',{method:'POST',data:{...confirmation,token:result.token}});
   stopScreen();$$('dialog').forEach(d=>d.remove());$('#printArea').innerHTML='';
   Object.keys(sessionStorage).filter(k=>k.startsWith('acceso.')).forEach(k=>sessionStorage.removeItem(k));
   Object.assign(state,{user:null,csrf:null,events:[],tariffs:[],stats:[],eventId:null,pending:null,lastSale:null,tab:null});
   authScreen(outcome.setupRequired);
   if(outcome.setupRequired)$('#auth input[name="setupCode"]').value=outcome.setupCode;
   toast('Restablecimiento completado. Respaldo guardado en backups.');
  });
 });
}
